SELECT /*selectMasterMdAmAuthorityManageList*/ AUTH_ID, NAME AS AUTH_NAME, AUTH_DC, CREATE_DT, USE_FLAG, ROLE_FLAG FROM KX_AUTHINFO WHERE 1=1
AND AUTH_ID LIKE '%' || #{st_auth_id} || '%'
AND NAME LIKE '%' || #{st_auth_name} || '%'
AND CREATE_DT BETWEEN #{st_from_date} AND #{st_to_date}
AND USE_FLAG = #{st_use_flag}
AND ROLE_FLAG = #{st_role_flag}
ORDER BY AUTH_ID, AUTH_NAME

